import { taskService } from "@/services/taskService";

export function useTasks(projectId: string, enabled = true) {
  return useQuery({
    queryKey: ["tasks", projectId],
    queryFn: () => taskService.getTasks(projectId),
    staleTime: 30_000,
    enabled,
  });
}
